def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Counts
    opp_d = opp.count('D')
    opp_c = n - opp_d
    my_d = me.count('D')

    # Endgame: with CC=3 < DC=5, defect late unless strong mutual cooperation value.
    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        # If opponent has been very cooperative and we are mutually cooperating, keep C
        if opp_d <= 1 and n >= 5:
            return 'C'
        return 'D'

    # First few moves: cooperate to establish cooperation.
    if n < 4:
        return 'C'

    # Detect pure defector early: punish hard but occasionally probe.
    if opp_c == 0:
        if n >= 10:
            if n % 9 == 0:
                return 'C'
        return 'D'

    # Detect very cooperative opponent: cooperate mostly, exploit sparingly but safely.
    if opp_d <= 1:
        # If last was D from opponent, retaliate once then forgive.
        if opp[-1] == 'D':
            return 'D'
        # Occasionally test but avoid triggering collapse; only late or rare.
        if n >= 6 and n % 13 == 0 and remaining > 5:
            return 'D'
        return 'C'

    # Recent windows
    look = 8 if n >= 8 else n
    recent_opp = opp[-look:]
    recent_d = recent_opp.count('D')
    recent_c = look - recent_d

    last_opp = opp[-1]
    last_me = me[-1]

    # Strong punishment for sustained recent defection.
    if recent_d >= 5:
        return 'D'
    if recent_d >= 3:
        # Mostly defect, small chance to restore cooperation if we haven't been too defecting.
        if my_d < opp_d and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Overall defection rate
    ratio = opp_d / n

    # If opponent heavily defective overall, defect mostly with rare probes.
    if ratio > 0.4:
        if n % 11 == 0:
            return 'C'
        return 'D'

    # If opponent moderately defective, retaliate to last D, otherwise cooperate.
    if last_opp == 'D':
        # If we just defected in response and opponent has high total cooperation,
        # occasionally return to C to avoid escalating.
        if last_me == 'D' and ratio < 0.25 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent last cooperated.
    if last_opp == 'C':
        # If opponent has a decent defection rate, be cautious: mirror-ish with forgiveness.
        if ratio > 0.25:
            if rng.random() < 0.15:
                return 'D'
            return 'C'
        # If our last move was D and they still cooperated, exploit a bit but not too much.
        if last_me == 'D':
            if recent_c >= look - 2 and rng.random() < 0.2:
                return 'D'
            return 'C'
        return 'C'

    return 'C'
